import { type SynapseEnhancedHttpClient, SynapseEnhancedError } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";

export interface IDbConfig {
    host: string;
    port: number;
    database: string;
    user: string;
    password?: string;
}

export interface IInitializationParams {
    init_key: string;
    db_config?: IDbConfig;
    features?: {
        friend_system?: boolean;
        private_chat?: boolean;
        voice_messages?: boolean;
        security_control?: boolean;
    };
}

export interface IInitializationResult {
    success: boolean;
    message: string;
    initialized_at?: string;
    features_enabled?: Record<string, boolean>;
}

export interface IModuleStatus {
    initialized: boolean;
    version: string;
    features: Record<string, boolean>;
    database: {
        connected: boolean;
        pool_size?: number;
        active_connections?: number;
    };
    uptime_seconds: number;
}

export interface IEnhancedInitApi {
    initialize(params: IInitializationParams): Promise<IInitializationResult>;
    getStatus(): Promise<IModuleStatus>;
    checkHealth(): Promise<boolean>;
    getConfig(): Promise<Record<string, unknown>>;
    reinitialize(params: IInitializationParams): Promise<IInitializationResult>;
}

export class EnhancedInitApi implements IEnhancedInitApi {
    private httpClient: SynapseEnhancedHttpClient;
    private readonly baseUrl = "/enhanced";

    public constructor(httpClient: SynapseEnhancedHttpClient) {
        this.httpClient = httpClient;
    }

    /**
     * Initialize the enhanced module
     */
    public async initialize(params: IInitializationParams): Promise<IInitializationResult> {
        if (!params.init_key || typeof params.init_key !== "string" || params.init_key.trim().length === 0) {
            throw new SynapseEnhancedError(
                "init_key is required and must be a non-empty string",
                ErrorCode.INVALID_PARAM,
            );
        }

        if (params.db_config) {
            if (!params.db_config.host || typeof params.db_config.host !== "string") {
                throw new SynapseEnhancedError(
                    "db_config.host is required and must be a string",
                    ErrorCode.INVALID_PARAM,
                );
            }
            if (
                typeof params.db_config.port !== "number" ||
                params.db_config.port < 1 ||
                params.db_config.port > 65535
            ) {
                throw new SynapseEnhancedError(
                    "db_config.port must be a number between 1 and 65535",
                    ErrorCode.INVALID_PARAM,
                );
            }
        }

        const response = await this.httpClient.post<{
            status: string;
            result?: IInitializationResult;
            error?: string;
        }>(`${this.baseUrl}/init`, params as unknown as Record<string, unknown>);

        if (response.data.status !== "ok") {
            throw new SynapseEnhancedError(
                response.data.error || "Failed to initialize enhanced module",
                ErrorCode.UNKNOWN,
            );
        }

        return response.data.result!;
    }

    /**
     * Get module status
     */
    public async getStatus(): Promise<IModuleStatus> {
        const response = await this.httpClient.get<{
            status: string;
            module_status?: IModuleStatus;
            error?: string;
        }>(`${this.baseUrl}/status`);

        if (response.data.status !== "ok") {
            throw new SynapseEnhancedError(response.data.error || "Failed to get module status", ErrorCode.UNKNOWN);
        }

        return response.data.module_status!;
    }

    /**
     * Check module health
     */
    public async checkHealth(): Promise<boolean> {
        try {
            const status = await this.getStatus();
            return status.initialized && status.database.connected;
        } catch {
            return false;
        }
    }

    /**
     * Get module configuration
     */
    public async getConfig(): Promise<Record<string, unknown>> {
        const response = await this.httpClient.get<{
            status: string;
            config?: Record<string, unknown>;
            error?: string;
        }>(`${this.baseUrl}/config`);

        if (response.data.status !== "ok") {
            throw new SynapseEnhancedError(response.data.error || "Failed to get module config", ErrorCode.UNKNOWN);
        }

        return response.data.config || {};
    }

    /**
     * Reinitialize the module (useful after configuration changes)
     */
    public async reinitialize(params: IInitializationParams): Promise<IInitializationResult> {
        return this.initialize(params);
    }

    /**
     * Check if module is already initialized
     */
    public async isInitialized(): Promise<boolean> {
        try {
            const status = await this.getStatus();
            return status.initialized;
        } catch {
            return false;
        }
    }

    /**
     * Get module version
     */
    public async getVersion(): Promise<string> {
        const status = await this.getStatus();
        return status.version;
    }

    /**
     * Get enabled features
     */
    public async getEnabledFeatures(): Promise<Record<string, boolean>> {
        const status = await this.getStatus();
        return status.features;
    }

    /**
     * Check if a specific feature is enabled
     */
    public async isFeatureEnabled(feature: string): Promise<boolean> {
        if (!feature || typeof feature !== "string" || feature.trim().length === 0) {
            throw new SynapseEnhancedError(
                "feature is required and must be a non-empty string",
                ErrorCode.INVALID_PARAM,
            );
        }

        const features = await this.getEnabledFeatures();
        return features[feature] || false;
    }

    /**
     * Get database connection status
     */
    public async getDatabaseStatus(): Promise<{
        connected: boolean;
        pool_size?: number;
        active_connections?: number;
    }> {
        const status = await this.getStatus();
        return status.database;
    }

    /**
     * Get module uptime in seconds
     */
    public async getUptime(): Promise<number> {
        const status = await this.getStatus();
        return status.uptime_seconds;
    }
}
